import React, { useEffect, useMemo, useState } from "react";
import axios from "axios";
import RunHistory from "./components/RunHistory";

const savedFusionBaseUrl = localStorage.getItem("fusionBaseUrl") || "";
const savedFusionUsername = localStorage.getItem("fusionUsername") || "";

function formatTime(date = new Date()) {
  return date.toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

function App() {
  const [runs, setRuns] = useState([]);
  const [orgCodes, setOrgCodes] = useState("");
  const [showHistory, setShowHistory] = useState(false);
  const [activeView, setActiveView] = useState("dashboard");
  const [activityLog, setActivityLog] = useState([
    { time: formatTime(), type: "info", text: "Application started." },
  ]);
  const [fusionCredentials, setFusionCredentials] = useState({
    baseUrl: savedFusionBaseUrl,
    username: savedFusionUsername,
    password: "",
  });
  const [rememberCredentials, setRememberCredentials] = useState(true);
  const [authenticated, setAuthenticated] = useState(false);
  const [loginLoading, setLoginLoading] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState(null);

  const latestRun = runs[0];
  const connectionLabel = authenticated ? "Connected" : "Disconnected";
  const selectedOrgLabel = orgCodes.trim() || "Backend default";

  const stats = useMemo(() => {
    if (!latestRun) {
      return {
        subinventories: 0,
        locators: 0,
        status: "No snapshot yet",
      };
    }

    return {
      subinventories: latestRun.subinventoryCount,
      locators: latestRun.locatorCount,
      status: latestRun.status,
    };
  }, [latestRun]);

  const addLog = (text, type = "info") => {
    setActivityLog((current) => [
      { time: formatTime(), type, text },
      ...current,
    ].slice(0, 60));
  };

  const fetchHistory = async () => {
    try {
      const res = await axios.get("/api/extraction/history");
      setRuns(res.data);
    } catch (err) {
      console.error("Failed to load history", err);
    }
  };

  useEffect(() => {
    fetchHistory();
  }, []);

  const handleCredentialChange = (field, value) => {
    setFusionCredentials((current) => ({
      ...current,
      [field]: value,
    }));
  };

  const verifyFusionCredentials = async () => {
    const res = await axios.post("/api/auth/login", fusionCredentials);

    if (rememberCredentials) {
      localStorage.setItem("fusionBaseUrl", res.data.fusion.baseUrl);
      localStorage.setItem("fusionUsername", res.data.fusion.username);
    } else {
      localStorage.removeItem("fusionBaseUrl");
      localStorage.removeItem("fusionUsername");
    }

    setFusionCredentials((current) => ({
      ...current,
      baseUrl: res.data.fusion.baseUrl,
      username: res.data.fusion.username,
    }));

    return res;
  };

  const handleLogin = async (event) => {
    event.preventDefault();
    setLoginLoading(true);
    setMessage(null);
    addLog("Testing Oracle Fusion connection...");

    try {
      await verifyFusionCredentials();
      setAuthenticated(true);
      setActiveView("dashboard");
      setMessage({ type: "success", text: "Fusion login successful." });
      addLog("Login connection test succeeded.", "success");
    } catch (err) {
      const errText = err.response?.data?.error || err.message;
      setAuthenticated(false);
      setMessage({ type: "error", text: errText });
      addLog(`Login failed: ${errText}`, "error");
    } finally {
      setLoginLoading(false);
    }
  };

  const handleLogout = () => {
    setAuthenticated(false);
    setActiveView("dashboard");
    setFusionCredentials((current) => ({
      ...current,
      password: "",
    }));
    setMessage(null);
    addLog("Logged out.");
  };

  const handleTestConnection = async () => {
    setLoading(true);
    setMessage(null);
    addLog("Testing Oracle Fusion connection...");

    try {
      await verifyFusionCredentials();
      setMessage({ type: "success", text: "Connection test succeeded." });
      addLog("Connection test succeeded.", "success");
    } catch (err) {
      const errText = err.response?.data?.error || err.message;
      setMessage({ type: "error", text: errText });
      addLog(`Connection test failed: ${errText}`, "error");
    } finally {
      setLoading(false);
    }
  };

  const handleToggleHistory = async () => {
    const nextShowHistory = !showHistory;
    setShowHistory(nextShowHistory);

    if (nextShowHistory) {
      await fetchHistory();
      addLog("Run history opened.");
    }
  };

  const handleRun = async () => {
    setLoading(true);
    setMessage(null);
    addLog(`Generating configuration snapshot for ${selectedOrgLabel}...`);

    try {
      const res = await axios.post("/api/extraction/run", {
        orgCodes,
        fusionCredentials,
      });
      const successText = `Snapshot generated successfully (${res.data.run.subinventoryCount} subinventories, ${res.data.run.locatorCount} locators).`;
      setMessage({ type: "success", text: successText });
      addLog(successText, "success");
      addLog("Excel workbook generated.");
      await fetchHistory();
    } catch (err) {
      const errText = err.response?.data?.error || err.message;
      setMessage({ type: "error", text: errText });
      addLog(`Snapshot failed: ${errText}`, "error");
      if (showHistory) {
        await fetchHistory();
      }
    } finally {
      setLoading(false);
    }
  };

  const renderAuthPage = () => (
    <main className="auth-page">
      <div className="window-title">Oracle Fusion Configuration Snapshot</div>
      <section className="login-card">
        <div className="login-brand">
          <h1>ConfigSnapshot</h1>
          <p>Oracle Fusion Cloud Configuration Extractor</p>
        </div>

        <form className="login-panel" onSubmit={handleLogin}>
          <label htmlFor="fusion-base-url">Oracle Fusion URL</label>
          <input
            id="fusion-base-url"
            value={fusionCredentials.baseUrl}
            onChange={(event) => handleCredentialChange("baseUrl", event.target.value)}
            placeholder="https://your-instance.oraclecloud.com"
            disabled={loginLoading}
            required
          />

          <label htmlFor="fusion-username">Username</label>
          <input
            id="fusion-username"
            value={fusionCredentials.username}
            onChange={(event) => handleCredentialChange("username", event.target.value)}
            placeholder="Fusion username"
            disabled={loginLoading}
            required
          />

          <label htmlFor="fusion-password">Password</label>
          <input
            id="fusion-password"
            type="password"
            value={fusionCredentials.password}
            onChange={(event) => handleCredentialChange("password", event.target.value)}
            placeholder="Password"
            disabled={loginLoading}
            required
          />

          <label className="checkbox-row">
            <input
              type="checkbox"
              checked={rememberCredentials}
              onChange={(event) => setRememberCredentials(event.target.checked)}
              disabled={loginLoading}
            />
            Remember URL and username
          </label>

          {message && (
            <p className={message.type === "success" ? "status-ok" : "status-fail"}>{message.text}</p>
          )}

          <div className="login-actions">
            <button className="outline-button" type="button" onClick={handleTestConnection} disabled={loginLoading}>
              Test Connection
            </button>
            <button type="submit" disabled={loginLoading}>
              {loginLoading ? "Checking..." : "Login"}
            </button>
          </div>
        </form>
      </section>
    </main>
  );

  const renderDashboard = () => (
    <>
      <div className="page-heading">
        <h1>Welcome back, {fusionCredentials.username || "User"}</h1>
        <p>Here is an overview of your Oracle Fusion configuration snapshot tool.</p>
      </div>

      <section className="metrics-grid">
        <article className="metric-card">
          <span className="metric-label">Oracle Connection</span>
          <strong className={authenticated ? "metric-success" : "metric-danger"}>{connectionLabel}</strong>
          <p>{fusionCredentials.baseUrl || "No Fusion URL selected."}</p>
        </article>
        <article className="metric-card">
          <span className="metric-label">Selected Organizations</span>
          <strong>{selectedOrgLabel}</strong>
          <p>Use Configuration Snapshot to change the extraction target.</p>
        </article>
        <article className="metric-card">
          <span className="metric-label">Last Snapshot</span>
          <strong>{latestRun ? new Date(latestRun.createdAt).toLocaleString() : "No snapshot yet"}</strong>
          <p>{latestRun ? `${latestRun.subinventoryCount} subinventories, ${latestRun.locatorCount} locators.` : "Run extraction to generate a workbook."}</p>
        </article>
      </section>

      <section className="panel-card">
        <h2>Quick Actions</h2>
        <div className="button-row">
          <button className="outline-button" onClick={handleTestConnection} disabled={loading}>
            Test Connection
          </button>
          <button onClick={() => setActiveView("snapshot")}>Generate Configuration Snapshot</button>
          <button onClick={handleToggleHistory}>{showHistory ? "Hide Run History" : "Show Run History"}</button>
        </div>
        {message && (
          <p className={message.type === "success" ? "status-ok" : "status-fail"}>{message.text}</p>
        )}
      </section>

      {showHistory && (
        <section className="panel-card">
          <h2>Recent Run History</h2>
          <div className="history-wrap">
            <RunHistory runs={runs} />
          </div>
        </section>
      )}
    </>
  );

  const renderSnapshot = () => (
    <>
      <div className="page-heading">
        <h1>Configuration Snapshot</h1>
        <p>Fetch, map, and export Oracle Fusion configuration data.</p>
      </div>

      <section className="panel-card">
        <h2>Snapshot Configuration</h2>
        <div className="field-group">
          <label htmlFor="org-codes">Organization name or code</label>
          <div className="input-action">
            <input
              id="org-codes"
              value={orgCodes}
              onChange={(event) => setOrgCodes(event.target.value)}
              placeholder="ALL, Vision Operations, M1"
              disabled={loading}
            />
            <button className="outline-button" onClick={handleToggleHistory} disabled={loading}>
              {showHistory ? "Hide History" : "History"}
            </button>
          </div>
          <p className="helper-text">Separate multiple organizations with commas. Leave blank to use the backend default.</p>
        </div>

        <div className="include-list">
          <label><input type="checkbox" checked readOnly /> Include Subinventories</label>
          <label><input type="checkbox" checked readOnly /> Include Locators</label>
        </div>

        <div className="button-row">
          <button className="outline-button" onClick={handleTestConnection} disabled={loading}>
            Test Connection
          </button>
          <button onClick={handleRun} disabled={loading}>
            {loading ? "Generating Snapshot..." : "Generate Snapshot"}
          </button>
          <button onClick={handleRun} disabled={loading}>
            {loading ? "Generating Excel..." : "Generate Excel Workbook"}
          </button>
        </div>
      </section>

      <section className="panel-card">
        <h2>Status</h2>
        <div className="progress-track">
          <span style={{ width: loading ? "78%" : latestRun ? "100%" : "12%" }} />
        </div>
        <div className="status-grid">
          <span>Subinventories: {stats.subinventories}</span>
          <span>Locators: {stats.locators}</span>
          <span>Last Run: {latestRun ? new Date(latestRun.createdAt).toLocaleString() : "Not available"}</span>
        </div>
        {message && (
          <p className={message.type === "success" ? "status-ok" : "status-fail"}>{message.text}</p>
        )}
      </section>

      {showHistory && (
        <section className="panel-card">
          <h2>Run History</h2>
          <div className="history-wrap">
            <RunHistory runs={runs} />
          </div>
        </section>
      )}
    </>
  );

  const renderLogs = () => (
    <>
      <div className="page-heading">
        <h1>Application Logs</h1>
        <p>View application activities and extraction events.</p>
      </div>

      <section className="panel-card">
        <div className="log-console">
          {activityLog.map((entry, index) => (
            <p className={`log-line log-${entry.type}`} key={`${entry.time}-${index}`}>
              <span>[{entry.time}]</span> {entry.text}
            </p>
          ))}
        </div>
        <div className="button-row">
          <button className="outline-button" onClick={() => setActivityLog([])}>Clear Logs</button>
          <button onClick={() => {
            setShowHistory(true);
            setActiveView("dashboard");
          }}>Open Run History</button>
        </div>
      </section>
    </>
  );

  const renderSettings = () => (
    <>
      <div className="page-heading">
        <h1>Settings</h1>
        <p>Application configuration for your current Fusion session.</p>
      </div>

      <section className="panel-card">
        <h2>Connection Settings</h2>
        <div className="field-grid">
          <label>
            Oracle Fusion URL
            <input
              value={fusionCredentials.baseUrl}
              onChange={(event) => handleCredentialChange("baseUrl", event.target.value)}
            />
          </label>
          <label>
            Username
            <input
              value={fusionCredentials.username}
              onChange={(event) => handleCredentialChange("username", event.target.value)}
            />
          </label>
          <label>
            Password
            <input
              type="password"
              value={fusionCredentials.password}
              onChange={(event) => handleCredentialChange("password", event.target.value)}
            />
          </label>
        </div>
        <div className="button-row">
          <button className="outline-button" onClick={handleTestConnection} disabled={loading}>
            Test Connection
          </button>
          <button onClick={handleTestConnection} disabled={loading}>
            Save Settings
          </button>
        </div>
        {message && (
          <p className={message.type === "success" ? "status-ok" : "status-fail"}>{message.text}</p>
        )}
      </section>
    </>
  );

  const renderContent = () => {
    if (activeView === "snapshot") return renderSnapshot();
    if (activeView === "logs") return renderLogs();
    if (activeView === "settings") return renderSettings();
    return renderDashboard();
  };

  if (!authenticated) {
    return renderAuthPage();
  }

  return (
    <main className="desktop-shell">
      <aside className="sidebar">
        <div>
          <div className="sidebar-brand">
            <strong>ConfigSnapshot</strong>
            <span>Oracle Fusion Config Tool</span>
          </div>

          <nav className="side-nav">
            <button className={activeView === "dashboard" ? "active" : ""} onClick={() => setActiveView("dashboard")}>Dashboard</button>
            <button className={activeView === "snapshot" ? "active" : ""} onClick={() => setActiveView("snapshot")}>Configuration Snapshot</button>
            <button className={activeView === "logs" ? "active" : ""} onClick={() => setActiveView("logs")}>Logs</button>
            <button className={activeView === "settings" ? "active" : ""} onClick={() => setActiveView("settings")}>Settings</button>
          </nav>
        </div>

        <div className="sidebar-footer">
          <p><span>Connection:</span><strong className="connected-dot">Connected</strong></p>
          <p><span>User:</span><strong>{fusionCredentials.username}</strong></p>
          <button className="sidebar-logout" onClick={handleLogout} disabled={loading}>Logout</button>
        </div>
      </aside>

      <section className="content-area">
        {renderContent()}
      </section>
    </main>
  );
}

export default App;
